cd /tmp/heatscratch && cat > p.mi <<'EOF'
use system.fs
use system.os
use system.collections.list

fn main()
    let fs = Fs()
    var text = ""
    match fs.read_file(Args().element_at(0))
        Result.Ok(t): text = t
        Result.Err: panic("x")
    var nums = List<int>()
    for line in text.split("\n")
        for tok in line.split(" ")
            let t = tok.trim()
            if not t.is_empty()
                match t.to_int()
                    Some(v): nums.push(v)
                    None: panic("bad")
    println(f"{nums.length()}")
EOF
miri build p.mi -o p >/dev/null && time ./p b0.txt

